import { __ } from '@wordpress/i18n';
import { BaseControl, Button, ButtonGroup } from '@wordpress/components';

const JoliOptionToggle = ( { label, value, onChange } ) => {
    return (
        <BaseControl>
            <div className="wpj-jtoc--label-container">
                <label>{label}</label>
            </div>
            <ButtonGroup>
                <Button
                    isSmall
                    variant={value == 1 ? 'primary' : 'secondary'}
                    onClick={() => onChange( 1 )}
                >{__( 'Yes', 'joli-table-of-contents' )}</Button>
                <Button
                    isSmall
                    variant={value == 0 ? 'primary' : 'secondary'}
                    onClick={() => onChange( 0 )}
                >{__( 'No', 'joli-table-of-contents' )}</Button>
            </ButtonGroup>
            <Button
                isSmall
                variant={value !== 0 && value !== 1 ? 'link' : 'tertiary'}
                // variant="link"
                onClick={() => onChange( -1 )}
            >{__( 'Inherit from settings', 'joli-table-of-contents' )}</Button>
        </BaseControl>
    );
}

export default JoliOptionToggle;