import { __ } from '@wordpress/i18n';
import { TextControl } from '@wordpress/components';

const JoliEditableListItem = ( { value, element, showInput, handleDoubleClick, handleChange, handleBlur } ) => {
	
	const handleKeyUp = (e) => {
		// console.log(e);
		if (e.code === 'Enter'){
			handleBlur( e );
		}
	}

	return (
		<div className="list-item-content">
			{showInput ?
				(
					<span className="list-item-override-input">
						<TextControl
							value={value}
							onChange={( value ) => handleChange( value )}
							onBlur={( e ) => handleBlur( e )}
							onKeyUp={( e ) => handleKeyUp( e )}
							autoFocus
							size={"small"}
						/>
					</span>
				) : (
					<span className="list-item-title"
						onDoubleClick={() => handleDoubleClick()}
					>{value}</span>
				)
			}

		</div>
	);
}

export default JoliEditableListItem;