import { __ } from '@wordpress/i18n';
import { BaseControl, ButtonGroup, Button } from '@wordpress/components';
import JoliFaqToggleIcon from "./JoliFaqToggleIcon";


const iconToggle1 = () => ( <JoliFaqToggleIcon iconClass="--jtoc-toggle-1" /> );
const iconToggle2 = () => ( <JoliFaqToggleIcon iconClass="--jtoc-toggle-2" /> );
const iconToggle3 = () => ( <JoliFaqToggleIcon iconClass="--jtoc-toggle-3" /> );
const iconToggle4 = () => ( <JoliFaqToggleIcon iconClass="--jtoc-toggle-4" /> );

const JoliToggleIconRadio = ( { label, value, onChange } ) => {
    return (
        <BaseControl>
            <div className="wpj-jtoc--label-container">
                <label>{label}</label>
            </div>
            <ButtonGroup>
                <Button
                    icon={iconToggle1}
                    variant={value == 'toggle-1' ? 'primary' : 'secondary'}
                    onClick={() => onChange( 'toggle-1' )}
                ></Button>
                <Button
                    icon={iconToggle2}
                    variant={value == 'toggle-2' ? 'primary' : 'secondary'}
                    onClick={() => onChange( 'toggle-2' )}
                ></Button>
                <Button
                    icon={iconToggle3}
                    variant={value == 'toggle-3' ? 'primary' : 'secondary'}
                    onClick={() => onChange( 'toggle-3' )}
                ></Button>
                <Button
                    icon={iconToggle4}
                    variant={value == 'toggle-4' ? 'primary' : 'secondary'}
                    onClick={() => onChange( 'toggle-4' )}
                ></Button>
            </ButtonGroup>
            <Button
                // isSmall
                variant={value !== -1 ? 'tertiary' : 'link'}
                // variant="link"
                onClick={() => onChange( -1 )}
            >{__( 'Inherit from settings', 'joli-table-of-contents' )}</Button>
        </BaseControl>
    );
}

export default JoliToggleIconRadio;

