import { __ } from '@wordpress/i18n';
import { BaseControl, Button, CheckboxControl } from '@wordpress/components';
import { useState, useEffect } from '@wordpress/element';

const JoliCheckboxes = ( { label, value, options, onChange } ) => {
// console.log(typeof value, value);
const propValue =  typeof value === 'string' ? value : "";
// console.log(propValue);
    const [activeOptions, setActiveOptions] = useState( propValue.split( ',' ) );
    // const [activeOptions, setActiveOptions] = useState( value );

    useEffect( () => {
        const newValue = activeOptions.join( ',' );
        onChange( newValue );
    }, [activeOptions] );

    const setChecked = ( checked, value ) => {
        let active = [...activeOptions];
        if ( checked == true && active.indexOf( value ) === -1 ) {
            active.push( value );
        } else {
            const index = active.indexOf( value );
            if ( index > -1 ) { // only splice array when item is found
                active.splice( index, 1 ); // 2nd parameter means remove one item only
            }
        }
        active = active.sort().filter(value => value !== "");

        // console.log( active );
        setActiveOptions( active );
    };

    const checkBoxList = ( () => {
        return options.map( element => {
            const isChecked = activeOptions.some( active => active == element.value );

            return (
                <CheckboxControl
                    key={element.value}
                    label={element.label}
                    data-value={element.value}
                    // help="Is the user a author or not?"
                    checked={isChecked}
                    onChange={( checked ) => setChecked( checked, element.value )}
                />
            );
        } );
    } )();

    const reset = () => {
        onChange( -1 );
        setActiveOptions( [] );
    }

    return (
        <BaseControl>
            <div className="wpj-jtoc--label-container">
                <label>{label}</label>
            </div>
            <div className="wpj-jtoc--joli-checkboxes-control">
                {checkBoxList}
            </div>
            <Button
                isSmall
                variant={value !== 0 && value !== 1 ? 'link' : 'tertiary'}
                // variant="link"
                onClick={() => reset()}
            >{__( 'Inherit from settings', 'joli-table-of-contents' )}</Button>
        </BaseControl>
    );
}

export default JoliCheckboxes;